def longest_common_substring(a, b):
    previous = [0] * (len(b) + 1)
    best = 0
    start_a = 0
    start_b = 0
    for i in range(1, len(a) + 1):
        current = [0] * (len(b) + 1)
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                current[j] = previous[j - 1] + 1
                if current[j] > best:
                    best = current[j]
                    start_a = i - best
                    start_b = j - best
        previous = current
    return {"length": best, "a_start": start_a, "b_start": start_b}

